        public function register_icon($icon_id) {
            if (isset($this->icons[$icon_id])) {
                $this->used_icons[$icon_id] = true;
            }
        }
        public function icon($icon_id) {
            if (isset($this->icons[$icon_id])) {
                $this->register_icon($icon_id);
                return '
                 <svg class=" ' . esc_attr($icon_id) . '"> <use href="#' . esc_attr($icon_id) . '"></use> </svg>
                ';
            }
            if (isset($this->animated_icons[$icon_id])) {
                $icon = $this->animated_icons[$icon_id];
                return '
                 <emdad-icon class="animated-icon ' . esc_attr($icon_id) . '" src="' . esc_url($icon['src']) . '" trigger="hover" colors="' . esc_attr($icon['colors']) . '"> </emdad-icon>
                ';
            }
            return '';
        }
        public function inject_svg_after_body($buffer) {
            if (empty($this->used_icons)) {
                return $buffer;
            }
            $body_pos = strpos($buffer, '<body');
            if ($body_pos === false) {
                return $buffer;
            }
            $insert_pos = strpos($buffer, '>', $body_pos);
            if ($insert_pos === false) {
                return $buffer;
            }
            $insert_pos++;
            $svg = '
                <svg xmlns="http://www.w3.org/2000/svg" style="display:none;">
            ';
            foreach ($this->used_icons as $id => $val) {
                if (isset($this->icons[$id])) {
                    $svg .= $this->icons[$id];
                }
            }
            $svg .= '</svg>';
            return substr_replace($buffer, $svg, $insert_pos, 0);
        }
        public function start_buffer() {
            ob_start([$this, 'inject_svg_after_body']);
        }
